17	package org.springframework.samples.petclinic.rest.controller;
18	
19	import java.time.LocalDate;
20	import java.util.Locale;
21	import java.util.Set;
22	import java.util.regex.Pattern;
23	
24	import org.slf4j.Logger;
25	import org.slf4j.LoggerFactory;
26	import org.springframework.http.HttpHeaders;
27	import org.springframework.http.HttpStatus;
28	import org.springframework.http.ResponseEntity;
29	import org.springframework.samples.petclinic.mapper.OwnerMapper;
30	import org.springframework.samples.petclinic.model.Owner;
31	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
32	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
33	import org.springframework.samples.petclinic.service.ClinicService;
34	import org.springframework.samples.petclinic.util.HashUtils;
35	import org.springframework.samples.petclinic.util.IdentityUtils;
36	import org.springframework.stereotype.Component;
37	import org.springframework.web.util.UriComponentsBuilder;
38	
39	/**
40	 * Owns the owner-creation concern: the single place that turns a submitted
41	 * {@link OwnerFieldsDto} into a validated, normalized, enriched and persisted {@link Owner},
42	 * and reports the create outcome as the HTTP response the endpoint returns.
43	 *
44	 * <p>Keeping the whole create pipeline here means every rule that fires on create — the
45	 * registration-date and business-day handling, the per-day and per-city quotas, the
46	 * address/telephone/email/postcode normalization and validation, the household, duplicate
47	 * and soft-match identity rules, and the derived customer code, namesake count and
48	 * membership number — reads the one owner this class builds, in the one order it applies
49	 * them, so they can never drift apart. The controller is left holding only the endpoint's
50	 * HTTP boundary.
51	 */
52	@Component
53	public class OwnerRegistrar {
54	
55	    /** Minimal syntactic check for an email address: a non-empty local part, a single
56	     *  '@', and a dotted domain, none containing whitespace or a second '@'. */
57	    private static final Pattern EMAIL_PATTERN =
58	        Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
59	
60	    /** A postcode, when supplied, must be exactly four digits before its region range is checked. */
61	    private static final Pattern POSTCODE_PATTERN = Pattern.compile("^[0-9]{4}$");
62	
63	    /** Disposable email domains that are rejected: an owner whose email domain matches one of
64	     *  these (case-insensitively) is refused with 400. */
65	    private static final java.util.Set<String> DISPOSABLE_EMAIL_DOMAINS =
66	        java.util.Set.of("mailinator.com", "tempmail.com", "guerrillamail.com");
67	
68	    /** Dedicated audit logger; emits an audit line on successful owner create. */
69	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
70	
71	    private final ClinicService clinicService;
72	
73	    private final OwnerMapper ownerMapper;
74	
75	    private final TelephoneNormalizer telephoneNormalizer;
76	
77	    private final AddressNormalizer addressNormalizer;
78	
79	    private final CityRegionResolver cityRegionResolver;
80	
81	    private final HouseholdResolver householdResolver;
82	
83	    /**
84	     * Remembers, per {@code Idempotency-Key}, the id of the owner that key's create originally
85	     * produced, so a later create carrying the same key returns that same owner instead of
86	     * creating a duplicate. The registrar is a singleton, so this store outlives a single
87	     * request; entries are keyed by the client-supplied key, which is expected to be unique
88	     * per logical create.
89	     */
90	    private final java.util.concurrent.ConcurrentHashMap<String, Integer> idempotencyKeys =
91	        new java.util.concurrent.ConcurrentHashMap<>();
92	
93	    public OwnerRegistrar(ClinicService clinicService,
94	                          OwnerMapper ownerMapper,
95	                          TelephoneNormalizer telephoneNormalizer,
96	                          AddressNormalizer addressNormalizer,
97	                          CityRegionResolver cityRegionResolver,
98	                          HouseholdResolver householdResolver) {
99	        this.clinicService = clinicService;
100	        this.ownerMapper = ownerMapper;
101	        this.telephoneNormalizer = telephoneNormalizer;
102	        this.addressNormalizer = addressNormalizer;
103	        this.cityRegionResolver = cityRegionResolver;
104	        this.householdResolver = householdResolver;
105	    }
106	
107	    /**
108	     * Validate, normalize, enrich and persist a new owner from the submitted fields, and
109	     * report the outcome as the response the create endpoint returns: {@code 201 Created}
110	     * (with a {@code Location} header and the created owner) on success, or the appropriate
111	     * rejection status ({@code 400}, {@code 409} or {@code 429}) when a create rule refuses
112	     * the request. No owner is persisted unless every rule passes.
113	     *
114	     * @param ownerFieldsDto the submitted owner fields
115	     * @return the create outcome as an HTTP response
116	     */
117	    public ResponseEntity<OwnerDto> register(OwnerFieldsDto ownerFieldsDto) {
118	        return register(ownerFieldsDto, null);
119	    }
120	
121	    /**
122	     * As {@link #register(OwnerFieldsDto)}, but honouring an optional {@code Idempotency-Key}.
123	     * When {@code idempotencyKey} is non-blank and a create with that key has already succeeded,
124	     * the owner it originally produced is returned with {@code 200 OK} instead of creating a
125	     * duplicate. Otherwise the normal create pipeline runs and, on success, the key is recorded
126	     * against the created owner so a later repeat resolves to the same owner.
127	     *
128	     * @param ownerFieldsDto the submitted owner fields
129	     * @param idempotencyKey the request's {@code Idempotency-Key} header, or {@code null} when absent
130	     * @return the create outcome as an HTTP response
131	     */
132	    public ResponseEntity<OwnerDto> register(OwnerFieldsDto ownerFieldsDto, String idempotencyKey) {
133	        String key = (idempotencyKey == null || idempotencyKey.isBlank()) ? null : idempotencyKey.trim();
134	        if (key != null) {
135	            Integer existingId = idempotencyKeys.get(key);
136	            if (existingId != null) {
137	                Owner original = this.clinicService.findOwnerById(existingId);
138	                if (original != null) {
139	                    return new ResponseEntity<>(ownerMapper.toOwnerDto(original), HttpStatus.OK);
140	                }
141	                // The originally created owner is gone; forget the stale key and create afresh.
142	                idempotencyKeys.remove(key);
143	            }
144	        }
145	        HttpHeaders headers = new HttpHeaders();
146	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
147	        if (owner.getRegistrationDate() == null) {
148	            owner.setRegistrationDate(LocalDate.now());
149	        }
150	        // A supplied registration date may not be later than the server's current date.
151	        if (owner.getRegistrationDate().isAfter(LocalDate.now())) {
152	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
153	        }
154	        owner.setRegistrationDate(toBusinessDay(owner.getRegistrationDate()));
155	        LocalDate registrationDate = owner.getRegistrationDate();
156	        long ownersCreatedThatDay = this.clinicService.findAllOwners().stream()
157	            .map(Owner::getRegistrationDate)
158	            .filter(registrationDate::equals)
159	            .count();
160	        if (ownersCreatedThatDay >= 100) {
161	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
162	        }
163	        String address = normalizedAddress(owner);
164	        if (address == null) {
165	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
166	        }
167	        owner.setAddress(address);
168	        String telephone = telephoneNormalizer.normalize(owner.getTelephone());
169	        if (telephone == null) {
170	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
171	        }
172	        if (!telephoneNormalizer.hasValidNationalNumberLength(telephone)) {
173	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
174	        }
175	        owner.setTelephone(telephone);
176	        String email = owner.getEmail();
177	        if (email != null) {
178	            email = email.trim();
179	            if (!EMAIL_PATTERN.matcher(email).matches()) {
180	                return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
181	            }
182	            String domain = email.substring(email.indexOf('@') + 1).toLowerCase(Locale.ROOT);
183	            if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
184	                return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
185	            }
186	            owner.setEmail(email.toLowerCase(Locale.ROOT));
187	        }
188	        // A postcode is optional, but when supplied it must be four digits and valid for the
189	        // owner's city per the fixed region table; a city with no known region accepts any
190	        // 4-digit postcode. Reject an out-of-range or malformed postcode with 400.
191	        String postcode = owner.getPostcode();
192	        if (postcode != null) {
193	            if (!POSTCODE_PATTERN.matcher(postcode).matches()
194	                    || !cityRegionResolver.isPostcodeValidForCity(owner.getCity(), postcode)) {
195	                return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
196	            }
197	        }
198	        // The owner's telephone and email are now in their canonical, stored form.
199	        // The household id is deterministic: owners with the same normalized last name and
200	        // postcode share it automatically. Assign it unconditionally before the duplicate
201	        // checks so both the household-duplicate rule and the identity-key rule key off the
202	        // same computed id.
203	        owner.setHouseholdId(householdResolver.householdId(owner));
204	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
205	        boolean householdMember = householdResolver.householdExists(owner);
206	        // Because the household is keyed on (lastName, postcode), a second owner sharing an
207	        // existing owner's household is a household duplicate and is rejected with 409. The
208	        // 'sharesHousehold' flag only bypasses this block, declaring a deliberate member; it
209	        // no longer creates the link, which the deterministic id now does on its own.
210	        if (householdMember && !sharesHousehold) {
211	            return new ResponseEntity<>(HttpStatus.CONFLICT);
212	        }
213	        if (isDuplicateOwner(owner)) {
214	            return new ResponseEntity<>(HttpStatus.CONFLICT);
215	        }
216	        String cityKey = IdentityUtils.normalizeIdentity(owner.getCity());
217	        long ownersInCity = this.clinicService.findAllOwners().stream()
218	            .filter(existing -> IdentityUtils.normalizeIdentity(existing.getCity()).equals(cityKey))
219	            .count();
220	        if (ownersInCity >= 50) {
221	            return new ResponseEntity<>(HttpStatus.CONFLICT);
222	        }
223	        owner.setCustomerCode(customerCode(owner));
224	        owner.setNamesakeCount(namesakeCount(owner));
225	        owner.setMembershipNumber(membershipNumber(owner.getCustomerCode(), owner.getRegistrationDate()));
226	        owner.setBulkSignupWarning(ownersCreatedThatDay > 80);
227	        // Soft-match: the candidate has already cleared the hard-duplicate check, but it may
228	        // still share an existing owner's last name and postcode while carrying a different
229	        // telephone. When it does, it is created but flagged as a possible duplicate of that
230	        // existing owner; otherwise the flag is false and no reference is recorded. A declared
231	        // household member (created via 'sharesHousehold') is not a suspected duplicate, so it
232	        // is never flagged.
233	        Integer possibleDuplicateOf = (sharesHousehold && householdMember) ? null : possibleDuplicateOf(owner);
234	        owner.setPossibleDuplicate(possibleDuplicateOf != null);
235	        owner.setPossibleDuplicateOf(possibleDuplicateOf);
236	        this.clinicService.saveOwner(owner);
237	        if (key != null) {
238	            idempotencyKeys.put(key, owner.getId());
239	        }
240	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
241	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
242	            ownerMapper.membershipLevel(owner), owner.getMembershipNumber());
243	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
244	        headers.setLocation(UriComponentsBuilder.newInstance()
245	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
246	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
247	    }
248	
249	    /**
250	     * The owner's postal address in the single canonical form under which it is stored, or
251	     * {@code null} when the owner supplies no usable address. An owner may supply its address
252	     * in EITHER form: the structured {@code addressLine1} (with an optional {@code addressLine2})
253	     * is preferred, and the flat {@code address} remains accepted for backward compatibility.
254	     *
255	     * <p>Normalization by {@link AddressNormalizer} is applied to whichever fields are supplied.
256	     * When a non-blank {@code addressLine1} is present the owner's structured fields are replaced
257	     * with their normalized values (a blank or absent {@code addressLine2} is cleared to
258	     * {@code null}) and the returned address is composed as the normalized {@code addressLine1},
259	     * with a single space and the normalized {@code addressLine2} appended when present. Otherwise
260	     * the flat {@code address} is normalized and the structured fields are cleared. A blank result
261	     * (no usable address in either form) has no canonical form and is reported as {@code null} so
262	     * the caller can reject the request with 400.
263	     *
264	     * <p>This is the single point at which an owner's address is resolved and normalized on
265	     * create, so every rule keyed on the stored address reads the one value produced here.
266	     *
267	     * @param owner the owner about to be created
268	     * @return the canonical stored address, or {@code null} when the owner supplies none
269	     */
270	    private String normalizedAddress(Owner owner) {
271	        String rawLine1 = owner.getAddressLine1();
272	        if (rawLine1 != null && !rawLine1.isBlank()) {
273	            String line1 = addressNormalizer.normalize(rawLine1);
274	            String line2 = addressNormalizer.normalize(owner.getAddressLine2());
275	            owner.setAddressLine1(line1);
276	            owner.setAddressLine2(line2.isBlank() ? null : line2);
277	            return line2.isBlank() ? line1 : line1 + " " + line2;
278	        }
279	        owner.setAddressLine1(null);
280	        owner.setAddressLine2(null);
281	        String address = addressNormalizer.normalize(owner.getAddress());
282	        return address.isBlank() ? null : address;
283	    }
284	
285	    /**
286	     * Whether {@code candidate} collides with an already-registered owner under the single
287	     * identity rule enforced on create. This is the one point at which a new owner is
288	     * rejected as a duplicate (HTTP 409): all duplicate detection is consolidated into the
289	     * derived {@link OwnerMapper#identityKey identityKey} — the normalized telephone, the
290	     * email (or an empty string when absent) and the householdId joined by '|'. The
291	     * candidate clashes only when its WHOLE identityKey equals an existing owner's; because
292	     * the telephone is part of the key, two members of the same household (same householdId)
293	     * with different telephones have different identityKeys and are both allowed.
294	     *
295	     * <p>The candidate arrives with its telephone and email already normalized and its
296	     * household id already derived, and each existing owner is stored in the same canonical
297	     * form, so an identityKey match means the two owners are genuinely the same identity.
298	     *
299	     * @param candidate the fully-normalized owner about to be created
300	     * @return {@code true} if an existing owner already occupies the candidate's identityKey
301	     */
302	    private boolean isDuplicateOwner(Owner candidate) {
303	        String identityKey = OwnerMapper.identityKey(candidate);
304	        return this.clinicService.findAllOwners().stream()
305	            .filter(existing -> !existing.isDeleted())
306	            .map(OwnerMapper::identityKey)
307	            .anyMatch(identityKey::equals);
308	    }
309	
310	    /**
311	     * The id of the existing owner the fully-normalized {@code candidate} soft-matches, or
312	     * {@code null} when there is none. A soft match is an owner that is not a hard duplicate
313	     * (its whole identityKey differs) yet shares the candidate's normalized last name and its
314	     * postcode while carrying a different telephone — a likely re-registration of the same
315	     * person under a new number. Both must supply a postcode for a match to be possible; when
316	     * several existing owners qualify the lowest id is returned so the result is deterministic.
317	     *
318	     * @param candidate the fully-normalized owner about to be created
319	     * @return the matching existing owner's id, or {@code null} if the candidate is no soft match
320	     */
321	    private Integer possibleDuplicateOf(Owner candidate) {
322	        String postcode = candidate.getPostcode();
323	        if (postcode == null) {
324	            return null;
325	        }
326	        String lastNameKey = IdentityUtils.normalizeIdentity(candidate.getLastName());
327	        return this.clinicService.findAllOwners().stream()
328	            .filter(existing -> !existing.isDeleted()
329	                && IdentityUtils.normalizeIdentity(existing.getLastName()).equals(lastNameKey)
330	                && postcode.equals(existing.getPostcode())
331	                && !postcode.isBlank()
332	                && !java.util.Objects.equals(candidate.getTelephone(), existing.getTelephone()))
333	            .map(Owner::getId)
334	            .filter(java.util.Objects::nonNull)
335	            .min(Integer::compareTo)
336	            .orElse(null);
337	    }
338	
339	    /**
340	     * Build the customer code assigned to {@code owner} on create, formatted
341	     * {@code '<REGION>-<HASH8>'}: REGION is the region code derived from the owner's postcode
342	     * (falling back to the city) via {@link CityRegionResolver}, and HASH8 is the first eight
343	     * upper-case hex characters of the SHA-256 digest of the normalized telephone concatenated
344	     * with the last name (e.g. 'NSW-1A2B3C4D'). There is no per-city sequence.
345	     *
346	     * <p>When the computed code collides with an already-registered owner's customerCode it is
347	     * de-duplicated by appending {@code '-<n>'} with the smallest {@code n} of 2 or more that
348	     * makes it unique (e.g. 'NSW-1A2B3C4D-2'), and the unique code is returned.
349	     */
350	    private String customerCode(Owner owner) {
351	        String region = cityRegionResolver.regionFor(owner.getCity(), owner.getPostcode());
352	        String hash8 = HashUtils.sha256HexPrefix(owner.getTelephone() + owner.getLastName(), 8);
353	        String base = region + "-" + hash8;
354	        java.util.Set<String> existing = this.clinicService.findAllOwners().stream()
355	            .map(Owner::getCustomerCode)
356	            .filter(java.util.Objects::nonNull)
357	            .collect(java.util.stream.Collectors.toSet());
358	        if (!existing.contains(base)) {
359	            return base;
360	        }
361	        int n = 2;
362	        while (existing.contains(base + "-" + n)) {
363	            n++;
364	        }
365	        return base + "-" + n;
366	    }
367	
368	    /**
369	     * The number of existing owners that share {@code owner}'s firstName and lastName,
370	     * compared case-insensitively. The candidate is not yet stored at the point this is
371	     * assigned, so it does not count itself. This is the value stored as the owner's
372	     * namesakeCount on create.
373	     */
374	    private int namesakeCount(Owner owner) {
375	        return (int) this.clinicService.findAllOwners().stream()
376	            .filter(existing -> owner.getFirstName().equalsIgnoreCase(existing.getFirstName())
377	                && owner.getLastName().equalsIgnoreCase(existing.getLastName()))
378	            .count();
379	    }
380	
381	    /** Fixed list of public holidays that a registration date must roll past. */
382	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
383	        LocalDate.of(2026, 1, 1),
384	        LocalDate.of(2026, 1, 26),
385	        LocalDate.of(2026, 4, 25),
386	        LocalDate.of(2026, 12, 25),
387	        LocalDate.of(2026, 12, 28));
388	
389	    /**
390	     * Roll a registration date forward to the next business day: a Saturday, Sunday
391	     * or listed public holiday advances one day at a time until it lands on a weekday
392	     * that is not a public holiday. A plain weekday is returned unchanged.
393	     */
394	    private static LocalDate toBusinessDay(LocalDate date) {
395	        while (isWeekend(date) || PUBLIC_HOLIDAYS.contains(date)) {
396	            date = date.plusDays(1);
397	        }
398	        return date;
399	    }
400	
401	    private static boolean isWeekend(LocalDate date) {
402	        return switch (date.getDayOfWeek()) {
403	            case SATURDAY, SUNDAY -> true;
404	            default -> false;
405	        };
406	    }
407	
408	    /**
409	     * Build the membership number assigned on create, formatted
410	     * {@code '<customerCode>-M<YY>'} where YY is the last two digits of the fiscal year of the
411	     * business-day-adjusted {@code registrationDate} (the fiscal year starts on 1 July), e.g.
412	     * 'NSW-1A2B3C4D-M26'.
413	     */
414	    private static String membershipNumber(String customerCode, LocalDate registrationDate) {
415	        String yy = String.format("%02d", OwnerMapper.fiscalYear(registrationDate) % 100);
416	        return customerCode + "-M" + yy;
417	    }
418	}
