22	/**
23	 * Maps Owner & OwnerDto using Mapstruct
24	 */
25	@Mapper(uses = PetMapper.class)
26	public abstract class OwnerMapper {
27	
28	    /** Used to count the members of an owner's household when deriving derived fields. */
29	    @Autowired
30	    protected ClinicService clinicService;
31	
32	    /** Single source of truth for the city-to-region mapping behind an owner's locality. */
33	    @Autowired
34	    protected CityRegionResolver cityRegionResolver;
35	
36	    /** Formats the stored E.164 telephone into its human-readable display form. */
37	    @Autowired
38	    protected TelephoneNormalizer telephoneNormalizer;
39	
40	    @Mapping(target = "selfLink", expression = "java(selfLink(owner))")
41	    @Mapping(target = "salutation", expression = "java(salutation(owner))")
42	    @Mapping(target = "displayName",
43	        expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
44	    @Mapping(target = "initials", expression = "java(initials(owner))")
45	    @Mapping(target = "membershipPoints", expression = "java(membershipPoints(owner))")
46	    @Mapping(target = "membershipLevel", expression = "java(membershipLevel(owner))")
47	    @Mapping(target = "locality", expression = "java(locality(owner))")
48	    @Mapping(target = "timezone", expression = "java(timezone(owner))")
49	    @Mapping(target = "contactPreference", expression = "java(contactPreference(owner))")
50	    @Mapping(target = "telephoneDisplay", expression = "java(telephoneNormalizer.toDisplayForm(owner.getTelephone()))")
51	    @Mapping(target = "identityKey", expression = "java(identityKey(owner))")
52	    @Mapping(target = "checkDigit", expression = "java(checkDigit(owner))")
53	    @Mapping(target = "ageBand", expression = "java(ageBand(owner))")
54	    @Mapping(target = "fiscalYear", expression = "java(fiscalYear(owner))")
55	    public abstract OwnerDto toOwnerDto(Owner owner);
56	
57	    /**
58	     * The owner's self link: '/api/owners/' followed by the owner's id, or null when the
59	     * owner has no id assigned yet.
60	     */
61	    String selfLink(Owner owner) {
62	        return owner.getId() == null ? null : "/api/owners/" + owner.getId();
63	    }
64	
65	    /**
66	     * The fiscal year (starting 1 July) that {@code date} falls in, identified by the
67	     * calendar year in which the fiscal year ends: a date in July–December belongs to the
68	     * fiscal year ending the following calendar year, while January–June belongs to the one
69	     * ending that same calendar year.
70	     */
71	    public static int fiscalYear(LocalDate date) {
72	        return date.getMonthValue() >= Month.JULY.getValue() ? date.getYear() + 1 : date.getYear();
73	    }
74	
75	    /**
76	     * The owner's fiscal year formatted 'FY<YY>', where YY is the last two digits of the
77	     * fiscal year of the (business-day-adjusted) {@code registrationDate} and the fiscal year
78	     * starts on 1 July. Returns null when no registrationDate has been assigned.
79	     */
80	    String fiscalYear(Owner owner) {
81	        LocalDate registrationDate = owner.getRegistrationDate();
82	        if (registrationDate == null) {
83	            return null;
84	        }
85	        return String.format("FY%02d", fiscalYear(registrationDate) % 100);
86	    }
87	
88	    /**
89	     * The owner's age band derived from {@code birthDate} relative to the
90	     * {@code registrationDate}: 'MINOR' when under 18, 'ADULT' from 18 to 64
91	     * inclusive and 'SENIOR' at 65 or older. Returns null when either date is
92	     * absent so no band can be computed.
93	     */
94	    OwnerDto.AgeBandEnum ageBand(Owner owner) {
95	        LocalDate birthDate = owner.getBirthDate();
96	        LocalDate registrationDate = owner.getRegistrationDate();
97	        if (birthDate == null || registrationDate == null) {
98	            return null;
99	        }
100	        int age = Period.between(birthDate, registrationDate).getYears();
101	        if (age < 18) {
102	            return OwnerDto.AgeBandEnum.MINOR;
103	        }
104	        if (age < 65) {
105	            return OwnerDto.AgeBandEnum.ADULT;
106	        }
107	        return OwnerDto.AgeBandEnum.SENIOR;
108	    }
109	
110	    /**
111	     * The owner's check digit: a single Luhn check digit (0-9) computed over the digits
112	     * contained in the customerCode, or null when no customerCode has been assigned.
113	     */
114	    Integer checkDigit(Owner owner) {
115	        String customerCode = owner.getCustomerCode();
116	        return customerCode == null ? null : luhn(customerCode);
117	    }
118	
119	    /**
120	     * The Luhn check digit (0-9) over the digits contained in {@code s}: from the rightmost
121	     * digit leftward, every second digit is doubled (the rightmost first) with digits over 9
122	     * reduced by 9, and the check digit makes the total a multiple of ten.
123	     */
124	    static int luhn(String s) {
125	        int sum = 0;
126	        boolean doubling = true;
127	        for (int i = s.length() - 1; i >= 0; i--) {
128	            char c = s.charAt(i);
129	            if (c < '0' || c > '9') {
130	                continue;
131	            }
132	            int d = c - '0';
133	            if (doubling) {
134	                d *= 2;
135	                if (d > 9) {
136	                    d -= 9;
137	                }
138	            }
139	            sum += d;
140	            doubling = !doubling;
141	        }
142	        return (10 - (sum % 10)) % 10;
143	    }
144	
145	    /**
146	     * The owner's derived identity key: the normalized telephone, the email (or an empty
147	     * string when absent) and the householdId joined by '|'. This single key is the sole
148	     * basis for duplicate detection on create — two owners are duplicates only when their
149	     * whole identityKey matches, so members of one household with different telephones
150	     * (and hence different keys) are all permitted.
151	     */
152	    public static String identityKey(Owner owner) {
153	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
154	        String email = owner.getEmail() == null ? "" : owner.getEmail();
155	        String householdId = owner.getHouseholdId() == null ? "" : owner.getHouseholdId();
156	        return telephone + "|" + email + "|" + householdId;
157	    }
158	
159	    /**
160	     * The owner's preferred contact channel: 'EMAIL' when an email address is
161	     * present, otherwise 'PHONE'.
162	     */
163	    String contactPreference(Owner owner) {
164	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
165	        return hasEmail ? "EMAIL" : "PHONE";
166	    }
167	
168	    /**
169	     * The owner's locality: the REGION component of the customerCode identity (the part before
170	     * the first '-' of {@code '<REGION>-<HASH8>'}). When no customerCode has been assigned this
171	     * falls back to the canonical region derived from the owner via {@link CityRegionResolver},
172	     * preferring the postcode over the city, or 'UNKNOWN' when neither yields a known region.
173	     */
174	    String locality(Owner owner) {
175	        String customerCode = owner.getCustomerCode();
176	        if (customerCode != null) {
177	            int dash = customerCode.indexOf('-');
178	            if (dash >= 0) {
179	                return customerCode.substring(0, dash);
180	            }
181	        }
182	        return cityRegionResolver.regionFor(owner.getCity(), owner.getPostcode());
183	    }
184	
185	    /**
186	     * The owner's IANA timezone name derived from the owner's {@link #locality(Owner) locality}
187	     * via the fixed region-to-timezone table (NSW -> Australia/Sydney, VIC -> Australia/Melbourne,
188	     * QLD -> Australia/Brisbane). Returns null when the locality is not a region in the table.
189	     */
190	    String timezone(Owner owner) {
191	        return cityRegionResolver.timezoneForRegion(locality(owner));
192	    }
193	
194	    /**
195	     * The owner's membership points: starting at 0, plus 2 when an email address is present,
196	     * plus 1 when namesakeCount is 0, plus 2 for a household of 3 or more members, plus 3 when
197	     * the owner's tenure is more than one fiscal year.
198	     */
199	    public int membershipPoints(Owner owner) {
200	        int points = 0;
201	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
202	        if (hasEmail) {
203	            points += 2;
204	        }
205	        boolean uniqueName = owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0;
206	        if (uniqueName) {
207	            points += 1;
208	        }
209	        if (householdSize(owner) >= 3) {
210	            points += 2;
211	        }
212	        LocalDate registrationDate = owner.getRegistrationDate();
213	        boolean tenured = registrationDate != null
214	            && fiscalYear(LocalDate.now()) - fiscalYear(registrationDate) > 1;
215	        if (tenured) {
216	            points += 3;
217	        }
218	        return points;
219	    }
220	
221	    /**
222	     * The owner's numeric membership level from 1 to 4, derived from {@link #membershipPoints}:
223	     * level 1 for 0-1 points, level 2 for 2-3 points, level 3 for 4-5 points and level 4 for
224	     * 6 or more points.
225	     */
226	    public int membershipLevel(Owner owner) {
227	        int points = membershipPoints(owner);
228	        if (points >= 6) {
229	            return 4;
230	        }
231	        if (points >= 4) {
232	            return 3;
233	        }
234	        if (points >= 2) {
235	            return 2;
236	        }
237	        return 1;
238	    }
239	
240	    /**
241	     * The number of owners belonging to {@code owner}'s household, i.e. those sharing its
242	     * householdId (including the owner itself once persisted). Returns 0 when the owner has no
243	     * household id assigned.
244	     */
245	    int householdSize(Owner owner) {
246	        String householdId = owner.getHouseholdId();
247	        if (householdId == null) {
248	            return 0;
249	        }
250	        return (int) clinicService.findAllOwners().stream()
251	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
252	            .count();
253	    }
254	
